def load():
    with open('data/astronomy/input/TLE/48445.tle', 'r') as f:
        lines = f.readlines()

    records = []
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line or line.startswith('#'):
            i += 1
            continue

        # Check if this is a line 1 of TLE
        if line.startswith('1 48445'):
            line1 = line
            if i + 1 < len(lines):
                line2 = lines[i + 1].strip()
                if line2.startswith('2 48445'):
                    records.append({
                        'line1': line1,
                        'line2': line2
                    })
                    i += 2
                else:
                    i += 1
            else:
                i += 1
        else:
            i += 1

    return pd.DataFrame(records)

def process(load_tle_data) -> pd.DataFrame:
    df = load_tle_data.copy()

    def parse_epoch(line1):
        try:
            year = int(line1[18:20])
            day_frac = float(line1[20:32])

            full_year = 2000 + year if year < 57 else 1900 + year
            day = int(day_frac)
            fraction = day_frac - day

            return pd.Timestamp(year=full_year, month=1, day=1) + pd.Timedelta(days=day-1) + pd.Timedelta(days=fraction)
        except Exception as e:
            return pd.NaT

    df['epoch'] = df['line1'].apply(parse_epoch)

    return df[['line1', 'line2', 'epoch']].copy()

