            distance = (position_km[0]**2 + position_km[1]**2 + position_km[2]**2)**0.5

            earth_radius = 6371.0
            altitude = distance - earth_radius

            results.append({
                'method': 'from_line',
                'success': True,
                'altitude_km': altitude,
                'error': None
            })
        except AttributeError as e:
            results.append({
                'method': 'from_line',
                'success': False,
                'altitude_km': None,
                'error': f'from_line failed: {str(e)}'
            })
        except Exception as e:
            results.append({
                'method': 'from_line',
                'success': False,
                'altitude_km': None,
                'error': str(e)
            })

    return pd.DataFrame(results)

