            fr = 0.0

            err, r, v = sat.sgp4(jd, fr)

            if err == 0 and r:
                x, y, z = r[0], r[1], r[2]
                r_mag = np.sqrt(x**2 + y**2 + z**2)
                earth_radius = 6371.0
                altitude_km = r_mag - earth_radius
                results.append({
                    'epoch': epoch_dt,
                    'method': 'sgp4_direct',
                    'success': True,
                    'altitude_km': altitude_km,
                    'error': None
                })
