def process(parse_tle_dates):
    from sgp4.api import Satrec
    import numpy as np

    results = []
    for _, row in parse_tle_dates.iterrows():
        try:
            line1 = row['line1']
            line2 = row['line2']
            epoch = row['epoch']

            sat = Satrec.twoline2rv(line1, line2)
            if sat.error == 0:
                jd = epoch.to_julian_date()
                fr = 0.0
                err, r, v = sat.sgp4(jd, fr)
                if err == 0:
                    r_km = np.linalg.norm(r)
                    altitude_km = r_km - 6371.0
                    results.append({'epoch': epoch, 'altitude_km': altitude_km})
                else:
